#!/usr/bin/env node
'use strict';

const readline = require('node:readline');

const [, , cmd, ...args] = process.argv;

function usage() {
  process.stderr.write(
    'usage: jsonl.js filter EXPR   # emit records where EXPR is truthy\n' +
    '       jsonl.js map EXPR      # emit EXPR evaluated per record\n' +
    '       jsonl.js count --by FIELD  # group counts as JSON\n'
  );
  process.exit(2);
}

function compile(expr) {
  // Each record is exposed to the user expression as `r`.
  return new Function('r', `return (${expr});`);
}

async function main() {
  if (!cmd) usage();

  const rl = readline.createInterface({ input: process.stdin });
  let malformed = 0;

  if (cmd === 'filter' || cmd === 'map') {
    const expr = args[0];
    if (!expr) usage();
    const fn = compile(expr);

    for await (const line of rl) {
      if (!line.trim()) continue;
      let r;
      try {
        r = JSON.parse(line);
      } catch {
        malformed++;
        continue;
      }
      if (cmd === 'filter') {
        try {
          if (fn(r)) process.stdout.write(JSON.stringify(r) + '\n');
        } catch {
          // Expression failure on this record: skip it.
        }
      } else {
        try {
          const s = JSON.stringify(fn(r));
          if (s !== undefined) process.stdout.write(s + '\n');
        } catch {
          // Expression failure on this record: skip it.
        }
      }
    }
  } else if (cmd === 'count') {
    const flagIdx = args.indexOf('--by');
    const field = flagIdx !== -1 ? args[flagIdx + 1] : undefined;
    if (!field || field.startsWith('-')) usage();

    const counts = Object.create(null);
    for await (const line of rl) {
      if (!line.trim()) continue;
      let r;
      try {
        r = JSON.parse(line);
      } catch {
        malformed++;
        continue;
      }
      const v = r[field];
      if (v === null || v === undefined) continue;
      const key = typeof v === 'object' ? JSON.stringify(v) : String(v);
      counts[key] = (counts[key] || 0) + 1;
    }

    const ordered = {};
    for (const k of Object.keys(counts).sort()) ordered[k] = counts[k];
    process.stdout.write(JSON.stringify(ordered) + '\n');
  } else {
    usage();
  }

  if (malformed > 0) {
    process.stderr.write(
      `jsonl: skipped ${malformed} malformed line(s)\n`
    );
  }
}

main().catch((err) => {
  process.stderr.write(`jsonl: ${err && err.stack ? err.stack : err}\n`);
  process.exit(1);
});

