'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const path = require('node:path');

const CLI = path.join(__dirname, 'jsonl.js');

function runCli(args, input) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [CLI, ...args]);
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => (stdout += d));
    child.stderr.on('data', (d) => (stderr += d));
    child.on('error', reject);
    child.on('close', (code) => resolve({ code, stdout, stderr }));
    child.stdin.end(input);
  });
}

// --- 20-record fixture: 18 valid records + 2 malformed lines ---
const records = [];
for (let i = 1; i <= 18; i++) {
  records.push({
    id: i,
    status: [200, 404, 500, 502][i % 4],
    level: ['info', 'warn', 'error'][i % 3],
    path: `/api/v1/item/${i}`,
  });
}
const MALFORMED_COUNT = 2;
const malformedLines = ['{oops', 'not json at all'];
const fixture =
  [...records.map((r) => JSON.stringify(r)), ...malformedLines].join('\n') +
  '\n';

test('filter r.status >= 500 selects exactly the server-error records', async () => {
  const { code, stdout, stderr } = await runCli(
    ['filter', 'r.status >= 500'],
    fixture
  );
  assert.equal(code, 0);

  const selected = stdout
    .split('\n')
    .filter(Boolean)
    .map((l) => JSON.parse(l));

  // status cycles [404, 500, 502, 200]: 500 when i%4===2, 502 when i%4===3
  const expectedIds = records
    .filter((r) => r.status >= 500)
    .map((r) => r.id)
    .sort((a, b) => a - b);

  assert.equal(selected.length, expectedIds.length);
  assert.deepEqual(selected.every((r) => r.status >= 500), true);
  assert.deepEqual(
    selected.map((r) => r.id).sort((a, b) => a - b),
    expectedIds
  );
});

test('map projecting two fields emits them per record', async () => {
  const projection = '{ status: r.status, path: r.path }';
  const { code, stdout } = await runCli(['map', projection], fixture);
  assert.equal(code, 0);

  const emitted = stdout
    .split('\n')
    .filter(Boolean)
    .map((l) => JSON.parse(l));

  assert.equal(emitted.length, records.length);
  emitted.forEach((row, idx) => {
    assert.deepEqual(Object.keys(row).sort(), ['path', 'status']);
    assert.deepEqual(row, {
      status: records[idx].status,
      path: records[idx].path,
    });
  });
});

test('count --by level groups correctly', async () => {
  const { code, stdout } = await runCli(['count', '--by', 'level'], fixture);
  assert.equal(code, 0);

  const counts = JSON.parse(stdout);
  // level cycles [info, warn, error] over 18 records -> 6 each
  assert.deepEqual(counts, { error: 6, info: 6, warn: 6 });
});

test('malformed lines are skipped and tallied on stderr', async () => {
  const { code, stdout, stderr } = await runCli(
    ['filter', 'r.id'],
    fixture
  );
  assert.equal(code, 0);
  assert.equal(stdout.split('\n').filter(Boolean).length, records.length);
  assert.match(stderr, new RegExp(`skipped ${MALFORMED_COUNT} malformed`));
});

